[data-part="offlog"]{position:relative !important;overflow:visible !important;padding-top:26px !important;padding-right:60px !important;background:repeating-linear-gradient(180deg,transparent 0 27px,rgba(158,200,255,.35) 27px 28px),#FFFBF4 !important}
